#!/usr/bin/env bash
#
# Post-`tauri ios init` patch for the iPhone build, the iOS counterpart of
# android-postinit-patch.sh. `client/src-tauri/gen/apple` is gitignored and regenerated by
# `tauri ios init`, which fills the AppIcon set with Tauri's placeholder logo; this copies the
# PS5Upload icons (client/src-tauri/icons/ios, drawn by ios-icons.py) over it. Run it AFTER
# init and BEFORE `tauri ios build`. Idempotent. Invoked from publish.yml, ios.yml and
# `make ios`.

set -euo pipefail

root="$(git rev-parse --show-toplevel 2>/dev/null || pwd)"
src="$root/client/src-tauri/icons/ios"
dst="$root/client/src-tauri/gen/apple/Assets.xcassets/AppIcon.appiconset"

if [ ! -d "$dst" ]; then
  echo "ios-postinit-patch: $dst is missing; run 'tauri ios init' first" >&2
  exit 1
fi

copied=0
for f in "$dst"/*.png; do
  name="$(basename "$f")"
  if [ ! -f "$src/$name" ]; then
    echo "ios-postinit-patch: no $name in $src (re-run scripts/release/ios-icons.py?)" >&2
    exit 1
  fi
  cp "$src/$name" "$f"
  copied=$((copied + 1))
done
[ "$copied" -gt 0 ] || { echo "ios-postinit-patch: no icons in $dst" >&2; exit 1; }
echo "ios-postinit-patch: $copied PS5Upload icons copied into the Xcode project"
